"use strict";var DailyEarning=function(n){var t={initialize:function(){DailyEarning.initEvent()},initEvent:function(){n("#dailyEarningContent").on("click",".dateItem",function(){DailyEarning.renderDailyEarningDetail()});n("#statementHistoryLink").on("click",function(){Site.reload()});n("#SportType").on("change",function(){var i=n("#MonthDate").val(),r=n(this).val();t.renderDailyEarning(i,r)})},renderDailyEarning:function(t,i){n.ajax({type:"GET",data:{monthDate:t,sportType:i},dataType:"html",cache:!1,url:Site.resolveRelativeUrl("UserPanel/GetDailyEarning"),success:function(t){n("#dailyEarningContent").html(t)}})},renderDailyEarningDetail:function(){n.ajax({type:"GET",dataType:"html",cache:!1,url:Site.resolveRelativeUrl("UserPanel/DailyEarningDetail"),success:function(t){n("#mainPanel").html(t)}})}};return t}(jQuery);DailyEarning.initialize();